"{0} ile yakın arkadaş oldunuz.": "You became close friends with {0}.",
"İlk adımlarını salondaki halının üstünde attın; elinden bırakmadığın şey plastik bir toptu.": "You took your first steps on the living-room rug, never letting go of a plastic ball.",
"Bir yaşındayken yuvarlanan her şeyin peşinden emekliyordun. Annen buna “top merakı” diyordu.": "At one you crawled after anything that rolled. Your mother called it \"ball fever\".",
"Deden sana küçük, deri bir top hediye etti. Ona bir isim bile koydun.": "Your grandfather gave you a small leather ball. You even gave it a name.",
"Baban {0} akşamları yorgun gelse de seninle salonda topu yuvarlamadan uyumuyordu.": "However tired he was, your father {0} never went to bed without rolling a ball with you.",
"Kreşte öğretmenin, diğer çocuklar oyuncaklarla oynarken senin hep bahçede top kovaladığını anlattı.": "Your nursery teacher said that while other kids played with toys, you were always chasing a ball outside.",
"İlk kez bir duvara top vurup döneni yakalamayı denedin. Saatlerce sürdü.": "For the first time you kicked a ball against a wall and tried to trap it. It went on for hours.",
"şehrin kulübünün": "the city club's",
"Babanın omzunda ilk kez {0} maçına gittin. Tribünün uğultusu o gece rüyalarına girdi.": "On your father's shoulders you went to your first {0} match. The roar of the crowd filled your dreams that night.",
"Kahvehanenin televizyonunda büyük bir maçı izledin; kalabalık her gol sesinde ayağa kalkıyordu ve sen de onlarla birlikte bağırıyordun.": "You watched a big match on the café TV; the crowd jumped up at every goal and you shouted along with them.",
"İlkokula başladın. Teneffüs zili çaldığında sınıftan ilk koşan hep sendin.": "You started primary school. When the break bell rang, you were always first out the door.",
"Baban {0} her akşam işten dönünce seninle parkta pas yapıyor; “sol ayağını da kullan” diye tekrarlıyor.": "Every evening after work your father {0} passes with you in the park, repeating \"use your left foot too\".",
"Mahallenin büyük çocukları seni artık kaleye değil, sahaya alıyor. Dizlerinde hiç kabuk eksik olmuyor.": "The older kids now put you outfield, not in goal. Your knees are never without scabs.",
"Odanın duvarında {0} posteri asılı; onun gol sevincini aynada çalışıyorsun.": "A poster of {0} hangs on your wall; you practise his celebration in the mirror.",
"Annen {0} karnene bakıp gülümsüyor. “Önce okul” sözünü tuttun.": "Your mother {0} smiles at your report card. You kept your \"school first\" promise.",
"{0} ile mahallede iki taştan kale kurup akşama kadar oynuyorsunuz.": "You and {0} make goals out of two stones and play until dark.",
"Mahalle turnuvasında ilk golünü attın ve sahayı bir uçtan bir uca koştun.": "You scored your first goal in the neighbourhood tournament and ran the length of the pitch.",
"Okul bahçesindeki maçlarda takımları kuran kişi oldun.": "You became the one who picks the teams in the schoolyard.",
"Kramponun yoktu; lastik ayakkabılarla oynuyordun ve burunları hep delikti. Annen gece yamıyordu.": "You had no boots; you played in rubber shoes with holes in the toes. Your mother patched them at night.",
"Doğum gününde ilk gerçek kramponların geldi. Bir hafta yatağının yanında uyudular.": "You got your first real boots for your birthday. They slept beside your bed for a week.",
"Futbol okulunda antrenörün tekniğine dikkat çekti; seni bir üst yaş grubuyla çalıştırıyor.": "Your coach at football school noticed your technique and trains you with the older age group.",
"{0} minikler takımıyla ilk deplasmanına gittin. Dönüşte otobüste herkes şarkı söylüyordu; kazanmıştınız.": "Your first away game with the {0} under-10s. Everyone sang on the bus home — you'd won.",
"Sokakta öğrendiğin çalımlar mahallede efsane oldu. “Topu ondan almak imkânsız” diyorlar.": "The tricks you learned in the street became legend. \"You can't get the ball off him,\" they say.",
"Okulun 100 metre yarışını açık farkla kazandın. Beden öğretmenin atletizm için ısrar ediyor.": "You won the school 100 metres by a mile. Your PE teacher insists on athletics.",
"Yaşıtın {0} ile aynı turnuvada karşılaştınız. O gün o iki gol attı, sen bir. Yolunuz bundan sonra hep kesişecek.": "You faced {0}, a boy your age, in a tournament. He scored two, you one. Your paths will keep crossing.",
"Yaz boyunca sabah erkenden çıkıp akşam ezanına kadar top oynadın.": "All summer you were out from dawn until dusk with a ball.",
"{0} yurdundaki ilk kışın zor geçti. Telefonda annenin sesini duyunca ağlamamak için kendini zor tuttun ama sabah antrenmanına herkesten önce çıktın.": "Your first winter in the {0} dorm was hard. You fought back tears hearing your mother on the phone, but you were first out for morning training.",
"{0} akademisinde yabancı bir dilde antrenman notu tutmayı öğrendin. Soyunma odasında ilk esprini yaptın ve herkes güldü.": "At the {0} academy you learned to take training notes in a foreign language. You cracked your first dressing-room joke and everyone laughed.",
"{0} altyapısında hafta sonları ligde oynuyorsun. Tribünde ailen hep aynı yerde, aynı battaniyenin altında.": "You play league games at weekends for the {0} academy. Your family is always in the same spot, under the same blanket.",
