"Savunmadasın. Oyuncun rakibi kendiliğinden kollar; dokunarak onu istediğin yere götür. Top rakipten açılınca MÜDAHALE et. KAYARAK daha uzağa uzanır ama faul riski büyük.": "You're defending. Your player tracks the opponent automatically; tap to move him where you want. TACKLE when the ball leaves the opponent's foot. SLIDE reaches further but risks a foul.",
"Penaltı: köşeye doğru sürükle. Uzun sürükleme sert ama kontrolsüz; kaleci bir tarafa atlayacak.": "Penalty: drag towards a corner. A long drag is powerful but wild; the keeper will dive one way.",
"Serbest vuruş: barajın yanından yay çizerek sürükle (falso) ya da “Havadan” ile barajın üstünden aşırt. Ceza sahasındaki arkadaşına orta da açabilirsin.": "Free kick: drag in an arc around the wall (curl) or use \"Lofted\" to go over it. You can also cross to a teammate in the box.",
"Orta geliyor! Top havadayken kaleye doğru sürükle: top sana gelince kafa ya da vole vurursun. Zamanlama önemli.": "Cross incoming! While the ball is in the air, drag towards goal: you'll head or volley it when it arrives. Timing matters.",
"Top sende, oyun durdu. Ekranda sürükle-bırak: ok yönü ve uzunluğu vuruşu belirler. Ok bir arkadaşını gösterirse otomatik pas olur. Kısa sürükleme topu önüne sürer ve oyun kısa süre akar.": "You have the ball and play is paused. Drag and release: the arrow's direction and length set the kick. Point at a teammate for an automatic pass. A short drag pushes the ball ahead and play runs briefly.",
