"Top kaçtı": "The ball got away",
"Topa doğru anda dokun!": "Tap the ball at the right moment!",
"Topun neresine vuracaksın? Yuvarlanan topa dokun: üst = alçak, alt = havalı, yan = falso.": "Where will you strike it? Tap the rolling ball: top = low, bottom = lofted, side = curl.",
"Kafayı tam vuramadın!": "You didn't get a clean header!",
