"DOKUN: KAFA!": "TAP: HEADER!",
"Rakip pas atmak üzere! Oyuncunu pas yoluna SÜRÜKLE ya da yola dokun: oraya koşar.": "The opponent is about to pass! DRAG your player into the passing lane or tap the lane: he runs there.",
"Bir pas daha geliyor, yolu kes!": "Another pass is coming, cut it out!",
