"Çalım koşusu! Oyuncun topla ileri koşuyor. Rakip önüne çıkınca ekranın SOLUNA ya da SAĞINA dokun (ya da kaydır): o yana sıyrılırsın. Doğru anda yaparsan rakip ters yöne gider.": "Dribbling run! Your player drives forward with the ball. When a defender steps in, tap the LEFT or RIGHT side of the screen: you sidestep that way. Time it right and he goes the wrong way.",
