"Canlı maç": "Live match",
"Spiker her anı yorumlar, tribün kaleye yaklaştıkça coşar. Sesi maç ekranındaki 🔊 düğmesiyle açıp kapatırsın.": "The commentator calls every moment and the crowd rises as you near goal. Toggle sound with the 🔊 button on the match screen.",
