"🔋 Geç dakikalarda kondisyonun düşükse yavaşlarsın. Yağmurda top kayar, karda yavaşlar, rüzgâr havadan topu sürükler.": "🔋 Late in the game, low fitness slows you down. Rain makes the ball skid, snow slows it, wind carries lofted balls.",
